# -*- coding: utf-8 -*-
"""Финальный нормализатор MMOSON_v7.docx.

Скрипт является последним слоем сборки: он устраняет остаточные фрагменты
старых ревизий, которые появлялись в поздних блоках build_docx_v7.py, и
приводит текст, таблицы и подписи к единой канонической модели.

Канон редакции 7.0 (09.09.2026):
* L1 Земля—Солнце; точка неустойчива, удержание непрерывное;
* два встречновращающихся цилиндра, R=5 км, Lцил=40 км, Lполная=49 км;
* реакторное освещение осевыми балками; зеркал и солнечного паруса нет;
* ось станции не поворачивается в инерциальном пространстве;
* Pэл=721,4 ГВт, Pтерм=1 603 ГВт, Pниз=677 ГВт при 60 °C;
* высокотемпературный сброс реакторов = 882 ГВт при 800 °C;
* полная радиационная площадь станции = 3 100,2 км² (1 550,1 на цилиндр).
"""
from __future__ import annotations

from copy import deepcopy
from pathlib import Path
import sys

from docx import Document

ROOT = Path(__file__).resolve().parents[1]
DEFAULT_DOC = ROOT / "MMOSON_v7.docx"


def _set_paragraph_text(paragraph, text: str) -> None:
    """Replace text while retaining the paragraph style and first-run font."""
    first_rpr = None
    if paragraph.runs:
        first_rpr = deepcopy(paragraph.runs[0]._r.rPr) if paragraph.runs[0]._r.rPr is not None else None
    for run in list(paragraph.runs):
        run._element.getparent().remove(run._element)
    run = paragraph.add_run(text)
    if first_rpr is not None:
        run._r.insert(0, deepcopy(first_rpr))


def _replace_para(paragraph, old: str, new: str) -> bool:
    text = paragraph.text
    if old not in text:
        return False
    _set_paragraph_text(paragraph, text.replace(old, new))
    return True


def _replace_prefix(doc, prefix: str, text: str) -> bool:
    for paragraph in doc.paragraphs:
        if paragraph.text.startswith(prefix):
            _set_paragraph_text(paragraph, text)
            return True
    # При повторном запуске документ уже нормализован; отсутствие старого
    # префикса тогда означает, что правка была выполнена ранее.
    return False


def _replace_contains(doc, needle: str, replacement: str, *, all_matches=False) -> int:
    n = 0
    for paragraph in doc.paragraphs:
        if needle in paragraph.text:
            if _replace_para(paragraph, needle, replacement):
                n += 1
                if not all_matches:
                    return n
    return n


def _set_cell(cell, text: str) -> None:
    # cell.text сохраняет границы ячейки и стиль таблицы; форматирование
    # числовых ячеек в исходнике единообразное.
    cell.text = text


def _cell_by_text(table, needle: str, replacement: str) -> bool:
    for row in table.rows:
        for cell in row.cells:
            if needle in cell.text:
                _set_cell(cell, replacement)
                return True
    return False


def _require_cell(table, needle: str, replacement: str) -> None:
    if not _cell_by_text(table, needle, replacement):
        raise ValueError(f"Не найдена ячейка: {needle!r}")


